package trail

import (
	"encoding/json"
	"fmt"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
	"github.com/entireio/cli/cmd/entire/cli/paths"

	"github.com/go-git/go-git/v5"
	"github.com/go-git/go-git/v5/plumbing"
	"github.com/go-git/go-git/v5/plumbing/filemode"
	"github.com/go-git/go-git/v5/plumbing/object"
)

const (
	metadataFile   = "metadata.json"
	discussionFile = "discussion.json"
)

// TrailStore provides CRUD operations for trail metadata on the entire/trails branch.
type TrailStore struct {
	repo *git.Repository
}

// NewTrailStore creates a new trail store backed by the given git repository.
func NewTrailStore(repo *git.Repository) *TrailStore {
	return &TrailStore{repo: repo}
}

// EnsureBranch creates the entire/trails orphan branch if it doesn't exist.
func (s *TrailStore) EnsureBranch() error {
	refName := plumbing.NewBranchReferenceName(paths.TrailsBranchName)
	_, err := s.repo.Reference(refName, true)
	if err == nil {
		return nil // Branch already exists
	}

	// Create orphan branch with empty tree
	emptyTreeHash, err := checkpoint.BuildTreeFromEntries(s.repo, make(map[string]object.TreeEntry))
	if err != nil {
		return fmt.Errorf("failed to build empty tree: %w", err)
	}

	authorName, authorEmail := checkpoint.GetGitAuthorFromRepo(s.repo)
	commitHash, err := s.createCommit(emptyTreeHash, plumbing.ZeroHash, "Initialize trails branch", authorName, authorEmail)
	if err != nil {
		return fmt.Errorf("failed to create initial commit: %w", err)
	}

	newRef := plumbing.NewHashReference(refName, commitHash)
	if err := s.repo.Storer.SetReference(newRef); err != nil {
		return fmt.Errorf("failed to set branch reference: %w", err)
	}
	return nil
}

// Write writes trail metadata and discussion to the entire/trails branch.
func (s *TrailStore) Write(metadata *TrailMetadata, discussion *TrailDiscussion) error {
	if metadata.TrailID.IsEmpty() {
		return fmt.Errorf("trail ID is required")
	}

	if err := s.EnsureBranch(); err != nil {
		return fmt.Errorf("failed to ensure trails branch: %w", err)
	}

	// Get current branch tree
	ref, entries, err := s.getBranchEntries()
	if err != nil {
		return fmt.Errorf("failed to get branch entries: %w", err)
	}

	// Build sharded path
	basePath := metadata.TrailID.Path() + "/"

	// Create metadata blob
	metadataJSON, err := json.MarshalIndent(metadata, "", "  ")
	if err != nil {
		return fmt.Errorf("failed to marshal metadata: %w", err)
	}
	metadataBlob, err := checkpoint.CreateBlobFromContent(s.repo, metadataJSON)
	if err != nil {
		return fmt.Errorf("failed to create metadata blob: %w", err)
	}
	entries[basePath+metadataFile] = object.TreeEntry{
		Name: basePath + metadataFile,
		Mode: filemode.Regular,
		Hash: metadataBlob,
	}

	// Create discussion blob
	if discussion == nil {
		discussion = &TrailDiscussion{Comments: []TrailComment{}}
	}
	discussionJSON, err := json.MarshalIndent(discussion, "", "  ")
	if err != nil {
		return fmt.Errorf("failed to marshal discussion: %w", err)
	}
	discussionBlob, err := checkpoint.CreateBlobFromContent(s.repo, discussionJSON)
	if err != nil {
		return fmt.Errorf("failed to create discussion blob: %w", err)
	}
	entries[basePath+discussionFile] = object.TreeEntry{
		Name: basePath + discussionFile,
		Mode: filemode.Regular,
		Hash: discussionBlob,
	}

	// Build tree and commit
	newTreeHash, err := checkpoint.BuildTreeFromEntries(s.repo, entries)
	if err != nil {
		return fmt.Errorf("failed to build tree: %w", err)
	}

	authorName, authorEmail := checkpoint.GetGitAuthorFromRepo(s.repo)
	commitMsg := fmt.Sprintf("Trail: %s (%s)", metadata.Title, metadata.TrailID)
	commitHash, err := s.createCommit(newTreeHash, ref.Hash(), commitMsg, authorName, authorEmail)
	if err != nil {
		return fmt.Errorf("failed to create commit: %w", err)
	}

	// Update branch ref
	newRef := plumbing.NewHashReference(plumbing.NewBranchReferenceName(paths.TrailsBranchName), commitHash)
	if err := s.repo.Storer.SetReference(newRef); err != nil {
		return fmt.Errorf("failed to update branch reference: %w", err)
	}

	return nil
}

// Read reads a trail by its ID from the entire/trails branch.
func (s *TrailStore) Read(trailID TrailID) (*TrailMetadata, *TrailDiscussion, error) {
	tree, err := s.getBranchTree()
	if err != nil {
		return nil, nil, err
	}

	basePath := trailID.Path() + "/"

	// Read metadata
	metadataEntry, err := tree.FindEntry(basePath + metadataFile)
	if err != nil {
		return nil, nil, fmt.Errorf("trail %s not found: %w", trailID, err)
	}
	metadataBlob, err := s.repo.BlobObject(metadataEntry.Hash)
	if err != nil {
		return nil, nil, fmt.Errorf("failed to read metadata blob: %w", err)
	}
	metadataReader, err := metadataBlob.Reader()
	if err != nil {
		return nil, nil, fmt.Errorf("failed to open metadata reader: %w", err)
	}
	defer metadataReader.Close()

	var metadata TrailMetadata
	if err := json.NewDecoder(metadataReader).Decode(&metadata); err != nil {
		return nil, nil, fmt.Errorf("failed to decode metadata: %w", err)
	}

	// Read discussion (optional, may not exist yet)
	var discussion TrailDiscussion
	discussionEntry, err := tree.FindEntry(basePath + discussionFile)
	if err == nil {
		discussionBlob, blobErr := s.repo.BlobObject(discussionEntry.Hash)
		if blobErr == nil {
			discussionReader, readerErr := discussionBlob.Reader()
			if readerErr == nil {
				_ = json.NewDecoder(discussionReader).Decode(&discussion)
				discussionReader.Close()
			}
		}
	}

	return &metadata, &discussion, nil
}

// FindByBranch finds a trail for the given branch name.
// Returns nil, nil if no trail exists for the branch.
func (s *TrailStore) FindByBranch(branchName string) (*TrailMetadata, error) {
	trails, err := s.List()
	if err != nil {
		return nil, err
	}

	for _, t := range trails {
		if t.Branch == branchName {
			return t, nil
		}
	}
	return nil, nil
}

// List returns all trail metadata from the entire/trails branch.
func (s *TrailStore) List() ([]*TrailMetadata, error) {
	tree, err := s.getBranchTree()
	if err != nil {
		// Branch doesn't exist yet — no trails
		return nil, nil //nolint:nilerr // Expected when no trails exist yet
	}

	var trails []*TrailMetadata
	entries := make(map[string]object.TreeEntry)
	if err := checkpoint.FlattenTree(s.repo, tree, "", entries); err != nil {
		return nil, fmt.Errorf("failed to flatten tree: %w", err)
	}

	// Find all metadata.json files
	for path, entry := range entries {
		if !strings.HasSuffix(path, "/"+metadataFile) {
			continue
		}

		blob, err := s.repo.BlobObject(entry.Hash)
		if err != nil {
			continue
		}
		reader, err := blob.Reader()
		if err != nil {
			continue
		}

		var metadata TrailMetadata
		decodeErr := json.NewDecoder(reader).Decode(&metadata)
		reader.Close()
		if decodeErr != nil {
			continue
		}

		trails = append(trails, &metadata)
	}

	return trails, nil
}

// Update updates an existing trail's metadata. It reads the current metadata,
// applies the provided update function, and writes it back.
func (s *TrailStore) Update(trailID TrailID, updateFn func(*TrailMetadata)) error {
	metadata, discussion, err := s.Read(trailID)
	if err != nil {
		return fmt.Errorf("failed to read trail for update: %w", err)
	}

	updateFn(metadata)
	metadata.UpdatedAt = time.Now()

	return s.Write(metadata, discussion)
}

// Delete removes a trail from the entire/trails branch.
func (s *TrailStore) Delete(trailID TrailID) error {
	ref, entries, err := s.getBranchEntries()
	if err != nil {
		return fmt.Errorf("failed to get branch entries: %w", err)
	}

	basePath := trailID.Path() + "/"

	// Remove entries for this trail
	found := false
	for path := range entries {
		if strings.HasPrefix(path, basePath) {
			delete(entries, path)
			found = true
		}
	}
	if !found {
		return fmt.Errorf("trail %s not found", trailID)
	}

	// Build tree and commit
	newTreeHash, err := checkpoint.BuildTreeFromEntries(s.repo, entries)
	if err != nil {
		return fmt.Errorf("failed to build tree: %w", err)
	}

	authorName, authorEmail := checkpoint.GetGitAuthorFromRepo(s.repo)
	commitMsg := fmt.Sprintf("Delete trail: %s", trailID)
	commitHash, err := s.createCommit(newTreeHash, ref.Hash(), commitMsg, authorName, authorEmail)
	if err != nil {
		return fmt.Errorf("failed to create commit: %w", err)
	}

	newRef := plumbing.NewHashReference(plumbing.NewBranchReferenceName(paths.TrailsBranchName), commitHash)
	if err := s.repo.Storer.SetReference(newRef); err != nil {
		return fmt.Errorf("failed to update branch reference: %w", err)
	}

	return nil
}

// getBranchTree returns the tree for the entire/trails branch HEAD.
func (s *TrailStore) getBranchTree() (*object.Tree, error) {
	refName := plumbing.NewBranchReferenceName(paths.TrailsBranchName)
	ref, err := s.repo.Reference(refName, true)
	if err != nil {
		// Try remote tracking branch
		remoteRefName := plumbing.NewRemoteReferenceName("origin", paths.TrailsBranchName)
		ref, err = s.repo.Reference(remoteRefName, true)
		if err != nil {
			return nil, fmt.Errorf("trails branch not found: %w", err)
		}
	}

	commit, err := s.repo.CommitObject(ref.Hash())
	if err != nil {
		return nil, fmt.Errorf("failed to get commit: %w", err)
	}

	tree, err := commit.Tree()
	if err != nil {
		return nil, fmt.Errorf("failed to get tree: %w", err)
	}

	return tree, nil
}

// getBranchEntries returns the current branch reference and a flat map of all tree entries.
func (s *TrailStore) getBranchEntries() (*plumbing.Reference, map[string]object.TreeEntry, error) {
	refName := plumbing.NewBranchReferenceName(paths.TrailsBranchName)
	ref, err := s.repo.Reference(refName, true)
	if err != nil {
		return nil, nil, fmt.Errorf("trails branch not found: %w", err)
	}

	commit, err := s.repo.CommitObject(ref.Hash())
	if err != nil {
		return nil, nil, fmt.Errorf("failed to get commit: %w", err)
	}

	tree, err := commit.Tree()
	if err != nil {
		return nil, nil, fmt.Errorf("failed to get tree: %w", err)
	}

	entries := make(map[string]object.TreeEntry)
	if err := checkpoint.FlattenTree(s.repo, tree, "", entries); err != nil {
		return nil, nil, fmt.Errorf("failed to flatten tree: %w", err)
	}

	return ref, entries, nil
}

// createCommit creates a commit on the trails branch.
func (s *TrailStore) createCommit(treeHash, parentHash plumbing.Hash, message, authorName, authorEmail string) (plumbing.Hash, error) {
	now := time.Now()
	sig := object.Signature{
		Name:  authorName,
		Email: authorEmail,
		When:  now,
	}

	commit := &object.Commit{
		TreeHash:  treeHash,
		Author:    sig,
		Committer: sig,
		Message:   message,
	}

	if parentHash != plumbing.ZeroHash {
		commit.ParentHashes = []plumbing.Hash{parentHash}
	}

	obj := s.repo.Storer.NewEncodedObject()
	if err := commit.Encode(obj); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to encode commit: %w", err)
	}

	hash, err := s.repo.Storer.SetEncodedObject(obj)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to store commit: %w", err)
	}

	return hash, nil
}

package cli

import (
	"encoding/json"
	"fmt"
	"io"
	"os"
	"sort"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
	"github.com/entireio/cli/cmd/entire/cli/strategy"
	"github.com/entireio/cli/cmd/entire/cli/trail"

	"github.com/charmbracelet/huh"
	"github.com/go-git/go-git/v5"
	"github.com/spf13/cobra"
)

func newTrailCmd() *cobra.Command {
	cmd := &cobra.Command{
		Use:   "trail",
		Short: "Manage trails for your branches",
		Long: `Trails are branch-centric work tracking abstractions. They describe the
"why" and "what" of your work, while checkpoints capture the "how" and "when".

Running 'entire trail' without a subcommand shows the trail for the current
branch, or lists all trails if no trail exists for the current branch.`,
		RunE: func(cmd *cobra.Command, _ []string) error {
			return runTrailShow(cmd.OutOrStdout())
		},
	}

	cmd.AddCommand(newTrailListCmd())
	cmd.AddCommand(newTrailCreateCmd())
	cmd.AddCommand(newTrailUpdateCmd())

	return cmd
}

// runTrailShow shows the trail for the current branch, or falls through to list.
func runTrailShow(w io.Writer) error {
	branch, err := GetCurrentBranch()
	if err != nil {
		return runTrailListAll(w, "", false)
	}

	repo, err := strategy.OpenRepository()
	if err != nil {
		return fmt.Errorf("failed to open repository: %w", err)
	}

	store := trail.NewTrailStore(repo)
	metadata, err := store.FindByBranch(branch)
	if err != nil || metadata == nil {
		return runTrailListAll(w, "", false)
	}

	printTrailDetails(w, metadata)
	return nil
}

func printTrailDetails(w io.Writer, m *trail.TrailMetadata) {
	fmt.Fprintf(w, "Trail: %s\n", m.Title)
	fmt.Fprintf(w, "  ID:      %s\n", m.TrailID)
	fmt.Fprintf(w, "  Branch:  %s\n", m.Branch)
	fmt.Fprintf(w, "  Base:    %s\n", m.Base)
	fmt.Fprintf(w, "  Status:  %s\n", m.Status)
	fmt.Fprintf(w, "  Author:  %s\n", m.Author)
	if m.Description != "" {
		fmt.Fprintf(w, "  Description: %s\n", m.Description)
	}
	if len(m.Labels) > 0 {
		fmt.Fprintf(w, "  Labels:  %s\n", strings.Join(m.Labels, ", "))
	}
	if len(m.Assignees) > 0 {
		fmt.Fprintf(w, "  Assignees: %s\n", strings.Join(m.Assignees, ", "))
	}
	fmt.Fprintf(w, "  Created: %s\n", m.CreatedAt.Format(time.RFC3339))
	fmt.Fprintf(w, "  Updated: %s\n", m.UpdatedAt.Format(time.RFC3339))
}

func newTrailListCmd() *cobra.Command {
	var statusFilter string
	var jsonOutput bool

	cmd := &cobra.Command{
		Use:   "list",
		Short: "List all trails",
		RunE: func(cmd *cobra.Command, _ []string) error {
			return runTrailListAll(cmd.OutOrStdout(), statusFilter, jsonOutput)
		},
	}

	cmd.Flags().StringVar(&statusFilter, "status", "", "Filter by status (draft, open, in_progress, in_review, done, closed)")
	cmd.Flags().BoolVar(&jsonOutput, "json", false, "Output as JSON")

	return cmd
}

func runTrailListAll(w io.Writer, statusFilter string, jsonOutput bool) error {
	repo, err := strategy.OpenRepository()
	if err != nil {
		return fmt.Errorf("failed to open repository: %w", err)
	}

	store := trail.NewTrailStore(repo)
	trails, err := store.List()
	if err != nil {
		return fmt.Errorf("failed to list trails: %w", err)
	}

	if trails == nil {
		trails = []*trail.TrailMetadata{}
	}

	// Apply status filter
	if statusFilter != "" {
		status := trail.TrailStatus(statusFilter)
		if !status.IsValid() {
			return fmt.Errorf("invalid status %q: valid values are %s", statusFilter, formatValidStatuses())
		}
		var filtered []*trail.TrailMetadata
		for _, t := range trails {
			if t.Status == status {
				filtered = append(filtered, t)
			}
		}
		trails = filtered
	}

	// Sort by updated_at descending
	sort.Slice(trails, func(i, j int) bool {
		return trails[i].UpdatedAt.After(trails[j].UpdatedAt)
	})

	if jsonOutput {
		enc := json.NewEncoder(w)
		enc.SetIndent("", "  ")
		return enc.Encode(trails)
	}

	if len(trails) == 0 {
		fmt.Fprintln(w, "No trails found.")
		fmt.Fprintln(w, "Create one with: entire trail create")
		return nil
	}

	// Table output
	fmt.Fprintf(w, "%-30s %-40s %-13s %-15s %s\n", "BRANCH", "TITLE", "STATUS", "AUTHOR", "UPDATED")
	for _, t := range trails {
		branch := truncate(t.Branch, 30)
		title := truncate(t.Title, 40)
		fmt.Fprintf(w, "%-30s %-40s %-13s %-15s %s\n",
			branch, title, t.Status, truncate(t.Author, 15), timeAgo(t.UpdatedAt))
	}

	return nil
}

func newTrailCreateCmd() *cobra.Command {
	var title, description, base, branch, status string

	cmd := &cobra.Command{
		Use:   "create",
		Short: "Create a trail for the current or a new branch",
		RunE: func(cmd *cobra.Command, _ []string) error {
			return runTrailCreate(cmd.OutOrStdout(), cmd.ErrOrStderr(), title, description, base, branch, status)
		},
	}

	cmd.Flags().StringVar(&title, "title", "", "Trail title")
	cmd.Flags().StringVar(&description, "description", "", "Trail description")
	cmd.Flags().StringVar(&base, "base", "", "Base branch (defaults to detected default branch)")
	cmd.Flags().StringVar(&branch, "branch", "", "Branch for the trail (defaults to current branch)")
	cmd.Flags().StringVar(&status, "status", "", "Initial status (defaults to draft)")

	return cmd
}

func runTrailCreate(w, errW io.Writer, title, description, base, branch, statusStr string) error {
	repo, err := strategy.OpenRepository()
	if err != nil {
		return fmt.Errorf("failed to open repository: %w", err)
	}

	// Determine branch
	if branch == "" {
		branch, err = GetCurrentBranch()
		if err != nil {
			return fmt.Errorf("failed to determine current branch: %w", err)
		}
	}

	// Check if on default branch
	isDefault, _, _ := IsOnDefaultBranch()
	if isDefault && branch == "" {
		fmt.Fprintln(errW, "Cannot create a trail on the default branch.")
		fmt.Fprintln(errW, "Create or switch to a feature branch first.")
		return NewSilentError(fmt.Errorf("cannot create trail on default branch"))
	}

	// Determine base branch
	if base == "" {
		base = strategy.GetDefaultBranchName(repo)
		if base == "" {
			base = "main"
		}
	}

	// Check if trail already exists for this branch
	store := trail.NewTrailStore(repo)
	existing, err := store.FindByBranch(branch)
	if err == nil && existing != nil {
		fmt.Fprintf(w, "Trail already exists for branch %q (ID: %s)\n", branch, existing.TrailID)
		return nil
	}

	// Determine title
	if title == "" {
		defaultTitle := trail.HumanizeBranchName(branch)

		// Interactive mode if flags not provided
		if !hasFlag("title") {
			var inputTitle string
			form := NewAccessibleForm(
				huh.NewGroup(
					huh.NewInput().
						Title("Trail title").
						Placeholder(defaultTitle).
						Value(&inputTitle),
				),
			)
			if formErr := form.Run(); formErr != nil {
				return fmt.Errorf("form cancelled: %w", formErr)
			}
			if inputTitle != "" {
				title = inputTitle
			} else {
				title = defaultTitle
			}
		} else {
			title = defaultTitle
		}
	}

	// Determine status
	var trailStatus trail.TrailStatus
	if statusStr != "" {
		trailStatus = trail.TrailStatus(statusStr)
		if !trailStatus.IsValid() {
			return fmt.Errorf("invalid status %q: valid values are %s", statusStr, formatValidStatuses())
		}
	} else {
		trailStatus = trail.StatusDraft
	}

	// Generate trail ID
	trailID, err := trail.GenerateID()
	if err != nil {
		return fmt.Errorf("failed to generate trail ID: %w", err)
	}

	// Get git author
	authorName, _ := checkpoint.GetGitAuthorFromRepo(repo)

	now := time.Now()
	metadata := &trail.TrailMetadata{
		TrailID:     trailID,
		Branch:      branch,
		Base:        base,
		Title:       title,
		Description: description,
		Status:      trailStatus,
		Author:      authorName,
		Assignees:   []string{},
		Labels:      []string{},
		CreatedAt:   now,
		UpdatedAt:   now,
	}

	if err := store.Write(metadata, nil); err != nil {
		return fmt.Errorf("failed to create trail: %w", err)
	}

	fmt.Fprintf(w, "Created trail %q for branch %s (ID: %s)\n", title, branch, trailID)
	return nil
}

func newTrailUpdateCmd() *cobra.Command {
	var statusStr, title, description, branch string
	var labelAdd, labelRemove []string

	cmd := &cobra.Command{
		Use:   "update",
		Short: "Update trail metadata",
		RunE: func(cmd *cobra.Command, _ []string) error {
			return runTrailUpdate(cmd.OutOrStdout(), statusStr, title, description, branch, labelAdd, labelRemove)
		},
	}

	cmd.Flags().StringVar(&statusStr, "status", "", "Update status")
	cmd.Flags().StringVar(&title, "title", "", "Update title")
	cmd.Flags().StringVar(&description, "description", "", "Update description")
	cmd.Flags().StringVar(&branch, "branch", "", "Branch to update trail for (defaults to current)")
	cmd.Flags().StringSliceVar(&labelAdd, "add-label", nil, "Add label(s)")
	cmd.Flags().StringSliceVar(&labelRemove, "remove-label", nil, "Remove label(s)")

	return cmd
}

func runTrailUpdate(w io.Writer, statusStr, title, description, branch string, labelAdd, labelRemove []string) error {
	repo, err := strategy.OpenRepository()
	if err != nil {
		return fmt.Errorf("failed to open repository: %w", err)
	}

	// Determine branch
	if branch == "" {
		branch, err = GetCurrentBranch()
		if err != nil {
			return fmt.Errorf("failed to determine current branch: %w", err)
		}
	}

	store := trail.NewTrailStore(repo)
	metadata, err := store.FindByBranch(branch)
	if err != nil {
		return fmt.Errorf("failed to find trail: %w", err)
	}
	if metadata == nil {
		return fmt.Errorf("no trail found for branch %q", branch)
	}

	// Validate status if provided
	if statusStr != "" {
		status := trail.TrailStatus(statusStr)
		if !status.IsValid() {
			return fmt.Errorf("invalid status %q: valid values are %s", statusStr, formatValidStatuses())
		}
	}

	err = store.Update(metadata.TrailID, func(m *trail.TrailMetadata) {
		if statusStr != "" {
			m.Status = trail.TrailStatus(statusStr)
		}
		if title != "" {
			m.Title = title
		}
		if description != "" {
			m.Description = description
		}
		for _, l := range labelAdd {
			if !containsString(m.Labels, l) {
				m.Labels = append(m.Labels, l)
			}
		}
		for _, l := range labelRemove {
			m.Labels = removeString(m.Labels, l)
		}
	})
	if err != nil {
		return fmt.Errorf("failed to update trail: %w", err)
	}

	fmt.Fprintf(w, "Updated trail for branch %s\n", branch)
	return nil
}

// AutoCreateTrail creates a trail automatically for the current branch if one doesn't exist.
// This is called during session start for non-main branches.
func AutoCreateTrail(repo *git.Repository, branchName, baseBranch string) error {
	store := trail.NewTrailStore(repo)

	existing, err := store.FindByBranch(branchName)
	if err == nil && existing != nil {
		return nil // Trail already exists
	}

	trailID, err := trail.GenerateID()
	if err != nil {
		return fmt.Errorf("failed to generate trail ID: %w", err)
	}

	authorName, _ := checkpoint.GetGitAuthorFromRepo(repo)
	now := time.Now()

	metadata := &trail.TrailMetadata{
		TrailID:     trailID,
		Branch:      branchName,
		Base:        baseBranch,
		Title:       trail.HumanizeBranchName(branchName),
		Status:      trail.StatusInProgress,
		Author:      authorName,
		Assignees:   []string{},
		Labels:      []string{},
		CreatedAt:   now,
		UpdatedAt:   now,
	}

	if err := store.Write(metadata, nil); err != nil {
		return fmt.Errorf("failed to create trail: %w", err)
	}

	fmt.Fprintf(os.Stderr, "[entire] Created trail for branch: %s\n", branchName)
	return nil
}

// hasFlag is a simple helper that checks os.Args for --flag presence.
// Used to distinguish between "flag not provided" and "flag provided with empty value".
func hasFlag(name string) bool {
	for _, arg := range os.Args {
		if arg == "--"+name || strings.HasPrefix(arg, "--"+name+"=") {
			return true
		}
	}
	return false
}

func truncate(s string, maxLen int) string {
	if len(s) <= maxLen {
		return s
	}
	if maxLen <= 3 {
		return s[:maxLen]
	}
	return s[:maxLen-3] + "..."
}

func formatValidStatuses() string {
	statuses := trail.ValidStatuses()
	names := make([]string, len(statuses))
	for i, s := range statuses {
		names[i] = string(s)
	}
	return strings.Join(names, ", ")
}

func containsString(slice []string, s string) bool {
	for _, v := range slice {
		if v == s {
			return true
		}
	}
	return false
}

func removeString(slice []string, s string) []string {
	var result []string
	for _, v := range slice {
		if v != s {
			result = append(result, v)
		}
	}
	return result
}

