	// First call should create the branch
	if err := store.EnsureBranch(); err != nil {
		t.Fatalf("EnsureBranch() error = %v", err)
	}

	// Second call should be idempotent
	if err := store.EnsureBranch(); err != nil {
		t.Fatalf("EnsureBranch() second call error = %v", err)
	}
}

func TestTrailStore_WriteAndRead(t *testing.T) {
	t.Parallel()
	repo := initTestRepo(t)
	store := NewTrailStore(repo)

	trailID, err := GenerateID()
	if err != nil {
		t.Fatalf("GenerateID() error = %v", err)
	}

	now := time.Now().Truncate(time.Second)
	metadata := &TrailMetadata{
		TrailID:     trailID,
		Branch:      "feature/test",
		Base:        "main",
		Title:       "Test trail",
		Description: "A test trail",
		Status:      StatusDraft,
		Author:      "tester",
		Assignees:   []string{},
		Labels:      []string{"test"},
		CreatedAt:   now,
		UpdatedAt:   now,
	}

	discussion := &TrailDiscussion{Comments: []TrailComment{}}

	if err := store.Write(metadata, discussion); err != nil {
		t.Fatalf("Write() error = %v", err)
	}

	// Read it back
	gotMeta, gotDisc, err := store.Read(trailID)
	if err != nil {
		t.Fatalf("Read() error = %v", err)
	}

	if gotMeta.TrailID != trailID {
		t.Errorf("Read() trail_id = %s, want %s", gotMeta.TrailID, trailID)
	}
	if gotMeta.Branch != "feature/test" {
		t.Errorf("Read() branch = %q, want %q", gotMeta.Branch, "feature/test")
	}
	if gotMeta.Title != "Test trail" {
		t.Errorf("Read() title = %q, want %q", gotMeta.Title, "Test trail")
	}
	if gotMeta.Status != StatusDraft {
		t.Errorf("Read() status = %q, want %q", gotMeta.Status, StatusDraft)
	}
	if len(gotMeta.Labels) != 1 || gotMeta.Labels[0] != "test" {
		t.Errorf("Read() labels = %v, want [test]", gotMeta.Labels)
	}
	if gotDisc == nil {
		t.Error("Read() discussion should not be nil")
	}
}

func TestTrailStore_FindByBranch(t *testing.T) {
	t.Parallel()
	repo := initTestRepo(t)
	store := NewTrailStore(repo)

	now := time.Now()

	// Create two trails for different branches
	for _, branch := range []string{"feature/a", "feature/b"} {
		id, _ := GenerateID()
		meta := &TrailMetadata{
			TrailID:   id,
			Branch:    branch,
			Base:      "main",
			Title:     HumanizeBranchName(branch),
			Status:    StatusDraft,
			Author:    "test",
			Assignees: []string{},
			Labels:    []string{},
			CreatedAt: now,
			UpdatedAt: now,
		}
		if err := store.Write(meta, nil); err != nil {
			t.Fatalf("Write() error = %v", err)
		}
	}

	// Find by branch
	found, err := store.FindByBranch("feature/a")
	if err != nil {
		t.Fatalf("FindByBranch() error = %v", err)
