	if len(trails) != 1 {
		t.Fatalf("List() returned %d trails, want 1", len(trails))
	}
	if trails[0].TrailID != id {
		t.Errorf("List()[0].TrailID = %s, want %s", trails[0].TrailID, id)
	}
}

func TestTrailStore_Update(t *testing.T) {
	t.Parallel()
	repo := initTestRepo(t)
	store := NewTrailStore(repo)

	now := time.Now()
	id, _ := GenerateID()
	meta := &TrailMetadata{
		TrailID:   id,
		Branch:    "feature/test",
		Base:      "main",
		Title:     "Original",
		Status:    StatusDraft,
		Author:    "test",
		Assignees: []string{},
		Labels:    []string{},
		CreatedAt: now,
		UpdatedAt: now,
	}
	if err := store.Write(meta, nil); err != nil {
		t.Fatalf("Write() error = %v", err)
	}

	// Update
	if err := store.Update(id, func(m *TrailMetadata) {
		m.Title = "Updated"
		m.Status = StatusInProgress
		m.Labels = []string{"urgent"}
	}); err != nil {
		t.Fatalf("Update() error = %v", err)
	}

	// Verify
	updated, _, err := store.Read(id)
	if err != nil {
		t.Fatalf("Read() error = %v", err)
	}
	if updated.Title != "Updated" {
		t.Errorf("Read() title = %q, want %q", updated.Title, "Updated")
	}
	if updated.Status != StatusInProgress {
		t.Errorf("Read() status = %q, want %q", updated.Status, StatusInProgress)
	}
	if len(updated.Labels) != 1 || updated.Labels[0] != "urgent" {
		t.Errorf("Read() labels = %v, want [urgent]", updated.Labels)
	}
	if !updated.UpdatedAt.After(now) {
		t.Error("Read() updated_at should be after original")
	}
}

func TestTrailStore_Delete(t *testing.T) {
	t.Parallel()
	repo := initTestRepo(t)
	store := NewTrailStore(repo)

	now := time.Now()
	id, _ := GenerateID()
	meta := &TrailMetadata{
		TrailID:   id,
