// Package trail provides types and helpers for managing trail metadata.
// Trails are branch-centric work tracking abstractions stored on the
// entire/trails orphan branch. They answer "why/what" (human intent)
// while checkpoints answer "how/when" (machine snapshots).
package trail

import (
	"crypto/rand"
	"encoding/hex"
	"fmt"
	"regexp"
	"strings"
	"time"
)

const idLength = 6 // 6 bytes = 12 hex chars

// ID is a 12-character hex identifier for trails.
type ID string

// EmptyID represents an unset or invalid trail ID.
const EmptyID ID = ""

// idRegex validates the format: exactly 12 lowercase hex characters.
var idRegex = regexp.MustCompile(`^[0-9a-f]{12}$`)

// GenerateID creates a new random 12-character hex trail ID.
func GenerateID() (ID, error) {
	bytes := make([]byte, idLength)
	if _, err := rand.Read(bytes); err != nil {
		return EmptyID, fmt.Errorf("failed to generate random trail ID: %w", err)
	}
	return ID(hex.EncodeToString(bytes)), nil
}

// ValidateID checks if a string is a valid trail ID format.
func ValidateID(s string) error {
	if !idRegex.MatchString(s) {
		return fmt.Errorf("invalid trail ID %q: must be 12 lowercase hex characters", s)
	}
	return nil
}

// String returns the trail ID as a string.
func (id ID) String() string {
	return string(id)
}

// IsEmpty returns true if the trail ID is empty or unset.
func (id ID) IsEmpty() bool {
	return id == EmptyID
}

// Path returns the sharded storage path for this trail ID.
// Uses first 2 characters as shard (256 buckets), remaining as folder name.
// Example: "a3b2c4d5e6f7" -> "a3/b2c4d5e6f7"
func (id ID) Path() string {
	if len(id) < 3 {
		return string(id)
	}
	return string(id[:2]) + "/" + string(id[2:])
}

// Status represents the lifecycle status of a trail.
type Status string

const (
	StatusDraft      Status = "draft"
	StatusOpen       Status = "open"
	StatusInProgress Status = "in_progress"
	StatusInReview   Status = "in_review"
	StatusDone       Status = "done"
	StatusClosed     Status = "closed"
)

// ValidStatuses returns all valid trail statuses in lifecycle order.
func ValidStatuses() []Status {
	return []Status{
		StatusDraft,
		StatusOpen,
		StatusInProgress,
		StatusInReview,
		StatusDone,
		StatusClosed,
	}
}

// IsValid returns true if the status is a recognized trail status.
func (s Status) IsValid() bool {
	for _, vs := range ValidStatuses() {
		if s == vs {
			return true
		}
	}
	return false
}

// Metadata represents the metadata for a trail, matching the web PR format.
type Metadata struct {
	TrailID     ID         `json:"trail_id"`
	Branch      string     `json:"branch"`
	Base        string     `json:"base"`
	Title       string     `json:"title"`
	Description string     `json:"description"`
	Status      Status     `json:"status"`
	Author      string     `json:"author"`
	Assignees   []string   `json:"assignees"`
	Labels      []string   `json:"labels"`
	CreatedAt   time.Time  `json:"created_at"`
	UpdatedAt   time.Time  `json:"updated_at"`
	MergedAt    *time.Time `json:"merged_at,omitempty"`
}

// Discussion holds the discussion/comments for a trail.
type Discussion struct {
	Comments []Comment `json:"comments"`
}

// Comment represents a single comment on a trail.
type Comment struct {
	ID        string         `json:"id"`
	Author    string         `json:"author"`
	Body      string         `json:"body"`
	CreatedAt time.Time      `json:"created_at"`
	Replies   []CommentReply `json:"replies,omitempty"`
}

// CommentReply represents a reply to a comment.
type CommentReply struct {
	ID        string    `json:"id"`
	Author    string    `json:"author"`
	Body      string    `json:"body"`
	CreatedAt time.Time `json:"created_at"`
}

// commonBranchPrefixes are stripped from branch names when humanizing.
var commonBranchPrefixes = []string{
	"feature/",
	"fix/",
	"bugfix/",
	"chore/",
	"hotfix/",
	"release/",
}

// HumanizeBranchName converts a branch name into a human-readable title.
// It strips common prefixes (feature/, fix/, etc.), replaces dashes/underscores
// with spaces, and capitalizes the first word.
func HumanizeBranchName(branch string) string {
	name := branch
	for _, prefix := range commonBranchPrefixes {
		if strings.HasPrefix(name, prefix) {
			name = strings.TrimPrefix(name, prefix)
			break
		}
	}

	// Replace - and _ with spaces
	name = strings.NewReplacer("-", " ", "_", " ").Replace(name)

	// Trim spaces and capitalize first letter
	name = strings.TrimSpace(name)
	if name == "" {
		return branch
	}

	// Capitalize first character
	return strings.ToUpper(name[:1]) + name[1:]
}

package trail

import (
	"encoding/json"
	"errors"
	"fmt"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
	"github.com/entireio/cli/cmd/entire/cli/paths"

	"github.com/go-git/go-git/v5"
	"github.com/go-git/go-git/v5/plumbing"
	"github.com/go-git/go-git/v5/plumbing/filemode"
	"github.com/go-git/go-git/v5/plumbing/object"
)

const (
	metadataFile   = "metadata.json"
	discussionFile = "discussion.json"
)

// ErrTrailNotFound is returned when a trail cannot be found.
var ErrTrailNotFound = errors.New("trail not found")

// Store provides CRUD operations for trail metadata on the entire/trails branch.
type Store struct {
	repo *git.Repository
}

// NewStore creates a new trail store backed by the given git repository.
func NewStore(repo *git.Repository) *Store {
	return &Store{repo: repo}
}

// EnsureBranch creates the entire/trails orphan branch if it doesn't exist.
func (s *Store) EnsureBranch() error {
	refName := plumbing.NewBranchReferenceName(paths.TrailsBranchName)
	_, err := s.repo.Reference(refName, true)
	if err == nil {
		return nil // Branch already exists
	}

	// Create orphan branch with empty tree
	emptyTreeHash, err := checkpoint.BuildTreeFromEntries(s.repo, make(map[string]object.TreeEntry))
	if err != nil {
		return fmt.Errorf("failed to build empty tree: %w", err)
	}

	authorName, authorEmail := checkpoint.GetGitAuthorFromRepo(s.repo)
	commitHash, err := s.createCommit(emptyTreeHash, plumbing.ZeroHash, "Initialize trails branch", authorName, authorEmail)
	if err != nil {
		return fmt.Errorf("failed to create initial commit: %w", err)
	}

	newRef := plumbing.NewHashReference(refName, commitHash)
	if err := s.repo.Storer.SetReference(newRef); err != nil {
		return fmt.Errorf("failed to set branch reference: %w", err)
	}
	return nil
}

// Write writes trail metadata and discussion to the entire/trails branch.
func (s *Store) Write(metadata *Metadata, discussion *Discussion) error {
	if metadata.TrailID.IsEmpty() {
		return errors.New("trail ID is required")
	}

	if err := s.EnsureBranch(); err != nil {
		return fmt.Errorf("failed to ensure trails branch: %w", err)
	}

	// Get current branch tree
	ref, entries, err := s.getBranchEntries()
	if err != nil {
		return fmt.Errorf("failed to get branch entries: %w", err)
	}

	// Build sharded path
	basePath := metadata.TrailID.Path() + "/"

	// Create metadata blob
	metadataJSON, err := json.MarshalIndent(metadata, "", "  ")
	if err != nil {
		return fmt.Errorf("failed to marshal metadata: %w", err)
	}
	metadataBlob, err := checkpoint.CreateBlobFromContent(s.repo, metadataJSON)
	if err != nil {
		return fmt.Errorf("failed to create metadata blob: %w", err)
	}
	entries[basePath+metadataFile] = object.TreeEntry{
		Name: basePath + metadataFile,
		Mode: filemode.Regular,
		Hash: metadataBlob,
	}

	// Create discussion blob
	if discussion == nil {
		discussion = &Discussion{Comments: []Comment{}}
	}
	discussionJSON, err := json.MarshalIndent(discussion, "", "  ")
	if err != nil {
		return fmt.Errorf("failed to marshal discussion: %w", err)
	}
	discussionBlob, err := checkpoint.CreateBlobFromContent(s.repo, discussionJSON)
	if err != nil {
		return fmt.Errorf("failed to create discussion blob: %w", err)
	}
	entries[basePath+discussionFile] = object.TreeEntry{
		Name: basePath + discussionFile,
		Mode: filemode.Regular,
		Hash: discussionBlob,
	}

	// Build tree and commit
	newTreeHash, err := checkpoint.BuildTreeFromEntries(s.repo, entries)
	if err != nil {
		return fmt.Errorf("failed to build tree: %w", err)
	}

	authorName, authorEmail := checkpoint.GetGitAuthorFromRepo(s.repo)
	commitMsg := fmt.Sprintf("Trail: %s (%s)", metadata.Title, metadata.TrailID)
	commitHash, err := s.createCommit(newTreeHash, ref.Hash(), commitMsg, authorName, authorEmail)
	if err != nil {
		return fmt.Errorf("failed to create commit: %w", err)
	}

	// Update branch ref
	newRef := plumbing.NewHashReference(plumbing.NewBranchReferenceName(paths.TrailsBranchName), commitHash)
	if err := s.repo.Storer.SetReference(newRef); err != nil {
		return fmt.Errorf("failed to update branch reference: %w", err)
	}

	return nil
}

// Read reads a trail by its ID from the entire/trails branch.
func (s *Store) Read(trailID ID) (*Metadata, *Discussion, error) {
	tree, err := s.getBranchTree()
	if err != nil {
		return nil, nil, err
	}

	basePath := trailID.Path() + "/"

	// Read metadata
	metadataEntry, err := tree.FindEntry(basePath + metadataFile)
	if err != nil {
		return nil, nil, fmt.Errorf("trail %s not found: %w", trailID, err)
	}
	metadataBlob, err := s.repo.BlobObject(metadataEntry.Hash)
	if err != nil {
		return nil, nil, fmt.Errorf("failed to read metadata blob: %w", err)
	}
	metadataReader, err := metadataBlob.Reader()
	if err != nil {
		return nil, nil, fmt.Errorf("failed to open metadata reader: %w", err)
	}
	defer metadataReader.Close()

	var metadata Metadata
	if err := json.NewDecoder(metadataReader).Decode(&metadata); err != nil {
		return nil, nil, fmt.Errorf("failed to decode metadata: %w", err)
	}

	// Read discussion (optional, may not exist yet)
	var discussion Discussion
	discussionEntry, err := tree.FindEntry(basePath + discussionFile)
	if err == nil {
		discussionBlob, blobErr := s.repo.BlobObject(discussionEntry.Hash)
		if blobErr == nil {
			discussionReader, readerErr := discussionBlob.Reader()
			if readerErr == nil {
				//nolint:errcheck // best-effort decode of optional discussion
				json.NewDecoder(discussionReader).Decode(&discussion)
				_ = discussionReader.Close()
			}
		}
	}

	return &metadata, &discussion, nil
}

// FindByBranch finds a trail for the given branch name.
// Returns nil, nil, nil if no trail exists for the branch.
func (s *Store) FindByBranch(branchName string) (*Metadata, error) {
	trails, err := s.List()
	if err != nil {
		return nil, err
	}

	for _, t := range trails {
		if t.Branch == branchName {
			return t, nil
		}
	}
	return nil, nil //nolint:nilnil // nil, nil means "not found" — callers check both
}

// List returns all trail metadata from the entire/trails branch.
func (s *Store) List() ([]*Metadata, error) {
	tree, err := s.getBranchTree()
	if err != nil {
		// Branch doesn't exist yet — no trails
		return nil, nil //nolint:nilerr // Expected when no trails exist yet
	}

	var trails []*Metadata
	entries := make(map[string]object.TreeEntry)
	if err := checkpoint.FlattenTree(s.repo, tree, "", entries); err != nil {
		return nil, fmt.Errorf("failed to flatten tree: %w", err)
	}

	// Find all metadata.json files
	for path, entry := range entries {
		if !strings.HasSuffix(path, "/"+metadataFile) {
			continue
		}

		blob, err := s.repo.BlobObject(entry.Hash)
		if err != nil {
			continue
		}
		reader, err := blob.Reader()
		if err != nil {
			continue
		}

		var metadata Metadata
		decodeErr := json.NewDecoder(reader).Decode(&metadata)
		_ = reader.Close()
		if decodeErr != nil {
			continue
		}

		trails = append(trails, &metadata)
	}

	return trails, nil
}

// Update updates an existing trail's metadata. It reads the current metadata,
// applies the provided update function, and writes it back.
func (s *Store) Update(trailID ID, updateFn func(*Metadata)) error {
	metadata, discussion, err := s.Read(trailID)
	if err != nil {
		return fmt.Errorf("failed to read trail for update: %w", err)
	}

	updateFn(metadata)
	metadata.UpdatedAt = time.Now()

	return s.Write(metadata, discussion)
}

// Delete removes a trail from the entire/trails branch.
func (s *Store) Delete(trailID ID) error {
	ref, entries, err := s.getBranchEntries()
	if err != nil {
		return fmt.Errorf("failed to get branch entries: %w", err)
	}

	basePath := trailID.Path() + "/"

	// Remove entries for this trail
	found := false
	for path := range entries {
		if strings.HasPrefix(path, basePath) {
			delete(entries, path)
			found = true
		}
	}
	if !found {
		return fmt.Errorf("trail %s not found", trailID)
	}

	// Build tree and commit
	newTreeHash, err := checkpoint.BuildTreeFromEntries(s.repo, entries)
	if err != nil {
		return fmt.Errorf("failed to build tree: %w", err)
	}

	authorName, authorEmail := checkpoint.GetGitAuthorFromRepo(s.repo)
	commitMsg := fmt.Sprintf("Delete trail: %s", trailID)
	commitHash, err := s.createCommit(newTreeHash, ref.Hash(), commitMsg, authorName, authorEmail)
	if err != nil {
		return fmt.Errorf("failed to create commit: %w", err)
	}

	newRef := plumbing.NewHashReference(plumbing.NewBranchReferenceName(paths.TrailsBranchName), commitHash)
	if err := s.repo.Storer.SetReference(newRef); err != nil {
		return fmt.Errorf("failed to update branch reference: %w", err)
	}

	return nil
}

// getBranchTree returns the tree for the entire/trails branch HEAD.
func (s *Store) getBranchTree() (*object.Tree, error) {
	refName := plumbing.NewBranchReferenceName(paths.TrailsBranchName)
	ref, err := s.repo.Reference(refName, true)
	if err != nil {
		// Try remote tracking branch
		remoteRefName := plumbing.NewRemoteReferenceName("origin", paths.TrailsBranchName)
		ref, err = s.repo.Reference(remoteRefName, true)
		if err != nil {
			return nil, fmt.Errorf("trails branch not found: %w", err)
		}
	}

	commit, err := s.repo.CommitObject(ref.Hash())
	if err != nil {
		return nil, fmt.Errorf("failed to get commit: %w", err)
	}

	tree, err := commit.Tree()
	if err != nil {
		return nil, fmt.Errorf("failed to get tree: %w", err)
	}

	return tree, nil
}

// getBranchEntries returns the current branch reference and a flat map of all tree entries.
func (s *Store) getBranchEntries() (*plumbing.Reference, map[string]object.TreeEntry, error) {
	refName := plumbing.NewBranchReferenceName(paths.TrailsBranchName)
	ref, err := s.repo.Reference(refName, true)
	if err != nil {
		return nil, nil, fmt.Errorf("trails branch not found: %w", err)
	}

	commit, err := s.repo.CommitObject(ref.Hash())
	if err != nil {
		return nil, nil, fmt.Errorf("failed to get commit: %w", err)
	}

	tree, err := commit.Tree()
	if err != nil {
		return nil, nil, fmt.Errorf("failed to get tree: %w", err)
	}

	entries := make(map[string]object.TreeEntry)
	if err := checkpoint.FlattenTree(s.repo, tree, "", entries); err != nil {
		return nil, nil, fmt.Errorf("failed to flatten tree: %w", err)
	}

	return ref, entries, nil
}

// createCommit creates a commit on the trails branch.
func (s *Store) createCommit(treeHash, parentHash plumbing.Hash, message, authorName, authorEmail string) (plumbing.Hash, error) {
	now := time.Now()
	sig := object.Signature{
		Name:  authorName,
		Email: authorEmail,
		When:  now,
	}

	commit := &object.Commit{
		TreeHash:  treeHash,
		Author:    sig,
		Committer: sig,
		Message:   message,
	}

	if parentHash != plumbing.ZeroHash {
		commit.ParentHashes = []plumbing.Hash{parentHash}
	}

	obj := s.repo.Storer.NewEncodedObject()
	if err := commit.Encode(obj); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to encode commit: %w", err)
	}

	hash, err := s.repo.Storer.SetEncodedObject(obj)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to store commit: %w", err)
	}

	return hash, nil
}

package trail

import (
	"testing"
)

func TestGenerateID(t *testing.T) {
	t.Parallel()

	id, err := GenerateID()
	if err != nil {
		t.Fatalf("GenerateID() error = %v", err)
	}
	if len(id) != 12 {
		t.Errorf("expected 12-char ID, got %d: %q", len(id), id)
	}
	if err := ValidateID(id.String()); err != nil {
		t.Errorf("generated ID failed validation: %v", err)
	}
}

func TestGenerateID_Unique(t *testing.T) {
	t.Parallel()

	seen := make(map[ID]bool)
	for range 100 {
		id, err := GenerateID()
		if err != nil {
			t.Fatalf("GenerateID() error = %v", err)
		}
		if seen[id] {
			t.Errorf("duplicate ID generated: %s", id)
		}
		seen[id] = true
	}
}

func TestValidateID(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name    string
		id      string
		wantErr bool
	}{
		{"valid", "abcdef123456", false},
		{"valid_all_hex", "0123456789ab", false},
		{"too_short", "abcdef", true},
		{"too_long", "abcdef1234567", true},
		{"uppercase", "ABCDEF123456", true},
		{"non_hex", "ghijkl123456", true},
		{"empty", "", true},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()
			err := ValidateID(tt.id)
			if (err != nil) != tt.wantErr {
				t.Errorf("ValidateID(%q) error = %v, wantErr %v", tt.id, err, tt.wantErr)
			}
		})
	}
}

func TestID_Path(t *testing.T) {
	t.Parallel()

	tests := []struct {
		id   ID
		want string
	}{
		{"abcdef123456", "ab/cdef123456"},
		{"0123456789ab", "01/23456789ab"},
		{"ab", "ab"},
	}

	for _, tt := range tests {
		t.Run(string(tt.id), func(t *testing.T) {
			t.Parallel()
			if got := tt.id.Path(); got != tt.want {
				t.Errorf("ID(%q).Path() = %q, want %q", tt.id, got, tt.want)
			}
		})
	}
}

func TestID_IsEmpty(t *testing.T) {
	t.Parallel()

	if !EmptyID.IsEmpty() {
		t.Error("EmptyID.IsEmpty() should return true")
	}
	id := ID("abcdef123456")
	if id.IsEmpty() {
		t.Error("non-empty ID.IsEmpty() should return false")
	}
}

func TestStatus_IsValid(t *testing.T) {
	t.Parallel()

	tests := []struct {
		status Status
		valid  bool
	}{
		{StatusDraft, true},
		{StatusOpen, true},
		{StatusInProgress, true},
		{StatusInReview, true},
		{StatusDone, true},
		{StatusClosed, true},
		{"invalid", false},
		{"", false},
	}

	for _, tt := range tests {
		t.Run(string(tt.status), func(t *testing.T) {
			t.Parallel()
			if got := tt.status.IsValid(); got != tt.valid {
				t.Errorf("Status(%q).IsValid() = %v, want %v", tt.status, got, tt.valid)
			}
		})
	}
}

func TestValidStatuses(t *testing.T) {
	t.Parallel()

	statuses := ValidStatuses()
	if len(statuses) != 6 {
		t.Errorf("expected 6 statuses, got %d", len(statuses))
	}
	// Verify lifecycle order
	expected := []Status{StatusDraft, StatusOpen, StatusInProgress, StatusInReview, StatusDone, StatusClosed}
	for i, s := range expected {
		if statuses[i] != s {
			t.Errorf("status[%d] = %q, want %q", i, statuses[i], s)
		}
	}
}

func TestHumanizeBranchName(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name   string
		branch string
		want   string
	}{
		{"feature prefix", "feature/add-auth", "Add auth"},
		{"fix prefix", "fix/login-bug", "Login bug"},
		{"bugfix prefix", "bugfix/typo-fix", "Typo fix"},
		{"chore prefix", "chore/update-deps", "Update deps"},
		{"hotfix prefix", "hotfix/security-patch", "Security patch"},
		{"release prefix", "release/v2.0", "V2.0"},
		{"no prefix", "add-auth", "Add auth"},
		{"underscores", "add_user_auth", "Add user auth"},
		{"mixed separators", "fix/some_complex-name", "Some complex name"},
		{"simple name", "main", "Main"},
		{"empty after prefix", "feature/", "feature/"},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()
			if got := HumanizeBranchName(tt.branch); got != tt.want {
				t.Errorf("HumanizeBranchName(%q) = %q, want %q", tt.branch, got, tt.want)
			}
		})
	}
}

package trail

import (
	"context"
	"os"
	"os/exec"
	"path/filepath"
	"testing"
	"time"

	"github.com/go-git/go-git/v5"
)

// initTestRepo creates a test git repository with an initial commit.
func initTestRepo(t *testing.T) *git.Repository {
	t.Helper()

	dir := t.TempDir()

	ctx := context.Background()
	cmds := [][]string{
		{"git", "init", dir},
		{"git", "-C", dir, "config", "user.name", "Test"},
		{"git", "-C", dir, "config", "user.email", "test@test.com"},
	}
	for _, args := range cmds {
		cmd := exec.CommandContext(ctx, args[0], args[1:]...)
		if out, err := cmd.CombinedOutput(); err != nil {
			t.Fatalf("command %v failed: %v\n%s", args, err, out)
		}
	}

	// Create a file and commit
	if err := os.WriteFile(filepath.Join(dir, "README.md"), []byte("# Test"), 0o644); err != nil {
		t.Fatalf("failed to write file: %v", err)
	}
	commitCmds := [][]string{
		{"git", "-C", dir, "add", "."},
		{"git", "-C", dir, "commit", "-m", "Initial commit"},
	}
	for _, args := range commitCmds {
		cmd := exec.CommandContext(ctx, args[0], args[1:]...)
		if out, err := cmd.CombinedOutput(); err != nil {
			t.Fatalf("command %v failed: %v\n%s", args, err, out)
		}
	}

	repo, err := git.PlainOpen(dir)
	if err != nil {
		t.Fatalf("failed to open repo: %v", err)
	}
	return repo
}

func TestStore_EnsureBranch(t *testing.T) {
	t.Parallel()
	repo := initTestRepo(t)
	store := NewStore(repo)

	// First call should create the branch
	if err := store.EnsureBranch(); err != nil {
		t.Fatalf("EnsureBranch() error = %v", err)
	}

	// Second call should be idempotent
	if err := store.EnsureBranch(); err != nil {
		t.Fatalf("EnsureBranch() second call error = %v", err)
	}
}

func TestStore_WriteAndRead(t *testing.T) {
	t.Parallel()
	repo := initTestRepo(t)
	store := NewStore(repo)

	trailID, err := GenerateID()
	if err != nil {
		t.Fatalf("GenerateID() error = %v", err)
	}

	now := time.Now().Truncate(time.Second)
	metadata := &Metadata{
		TrailID:     trailID,
		Branch:      "feature/test",
		Base:        "main",
		Title:       "Test trail",
		Description: "A test trail",
		Status:      StatusDraft,
		Author:      "tester",
		Assignees:   []string{},
		Labels:      []string{"test"},
		CreatedAt:   now,
		UpdatedAt:   now,
	}

	discussion := &Discussion{Comments: []Comment{}}

	if err := store.Write(metadata, discussion); err != nil {
		t.Fatalf("Write() error = %v", err)
	}

	// Read it back
	gotMeta, gotDisc, err := store.Read(trailID)
	if err != nil {
		t.Fatalf("Read() error = %v", err)
	}

	if gotMeta.TrailID != trailID {
		t.Errorf("Read() trail_id = %s, want %s", gotMeta.TrailID, trailID)
	}
	if gotMeta.Branch != "feature/test" {
		t.Errorf("Read() branch = %q, want %q", gotMeta.Branch, "feature/test")
	}
	if gotMeta.Title != "Test trail" {
		t.Errorf("Read() title = %q, want %q", gotMeta.Title, "Test trail")
	}
	if gotMeta.Status != StatusDraft {
		t.Errorf("Read() status = %q, want %q", gotMeta.Status, StatusDraft)
	}
	if len(gotMeta.Labels) != 1 || gotMeta.Labels[0] != "test" {
		t.Errorf("Read() labels = %v, want [test]", gotMeta.Labels)
	}
	if gotDisc == nil {
		t.Error("Read() discussion should not be nil")
	}
}

func TestStore_FindByBranch(t *testing.T) {
	t.Parallel()
	repo := initTestRepo(t)
	store := NewStore(repo)

	now := time.Now()

	// Create two trails for different branches
	for _, branch := range []string{"feature/a", "feature/b"} {
		id, err := GenerateID()
		if err != nil {
			t.Fatalf("GenerateID() error = %v", err)
		}
		meta := &Metadata{
			TrailID:   id,
			Branch:    branch,
			Base:      "main",
			Title:     HumanizeBranchName(branch),
			Status:    StatusDraft,
			Author:    "test",
			Assignees: []string{},
			Labels:    []string{},
			CreatedAt: now,
			UpdatedAt: now,
		}
		if err := store.Write(meta, nil); err != nil {
			t.Fatalf("Write() error = %v", err)
		}
	}

	// Find by branch
	found, err := store.FindByBranch("feature/a")
	if err != nil {
		t.Fatalf("FindByBranch() error = %v", err)
	}
	if found == nil {
		t.Fatal("FindByBranch() returned nil, expected trail")
	}
	if found.Branch != "feature/a" {
		t.Errorf("FindByBranch() branch = %q, want %q", found.Branch, "feature/a")
	}

	// Not found
	notFound, err := store.FindByBranch("feature/c")
	if err != nil {
		t.Fatalf("FindByBranch() error = %v", err)
	}
	if notFound != nil {
		t.Error("FindByBranch() should return nil for non-existent branch")
	}
}

func TestStore_List(t *testing.T) {
	t.Parallel()
	repo := initTestRepo(t)
	store := NewStore(repo)

	// List when no trails exist (branch doesn't exist yet)
	trails, err := store.List()
	if err != nil {
		t.Fatalf("List() error = %v", err)
	}
	if trails != nil {
		t.Errorf("List() = %v, want nil for empty store", trails)
	}

	// Create a trail
	now := time.Now()
	id, err := GenerateID()
