		Status:    StatusDraft,
		Author:    "test",
		Assignees: []string{},
		Labels:    []string{},
		CreatedAt: now,
		UpdatedAt: now,
	}
	if err := store.Write(meta, nil); err != nil {
		t.Fatalf("Write() error = %v", err)
	}

	// Delete
	if err := store.Delete(id); err != nil {
		t.Fatalf("Delete() error = %v", err)
	}

	// Verify it's gone
	_, _, err = store.Read(id)
	if err == nil {
		t.Error("Read() should fail after delete")
	}
}

func TestStore_ReadNonExistent(t *testing.T) {
	t.Parallel()
	repo := initTestRepo(t)
	store := NewStore(repo)

	if err := store.EnsureBranch(); err != nil {
		t.Fatalf("EnsureBranch() error = %v", err)
	}

	_, _, err := store.Read(ID("abcdef123456"))
	if err == nil {
		t.Error("Read() should fail for non-existent trail")
	}
}

