421→func truncate(s string, maxLen int) string {
422→	if len(s) <= maxLen {
423→		return s
424→	}
425→	if maxLen <= 3 {
426→		return s[:maxLen]
427→	}
428→	return s[:maxLen-3] + "..."
429→}
